package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class FastMath_max_TriageGen1Test {

    @Test
    public void testMax_aLessThanB() {
        float a = 1.0f;
        float b = 2.0f;
        float expected = 2.0f;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_aEqualsB() {
        float a = 5.0f;
        float b = 5.0f;
        float expected = 5.0f;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_aGreaterThanB() {
        // This covers the case where (a <= b) is false, 
        // and we need to check the ternary (Float.isNaN(a + b) ? Float.NaN : b)
        // To trigger the 'b' result, (a+b) must not be NaN.
        float a = 10.0f;
        float b = 5.0f;
        // Note: Based on the provided implementation: (a <= b) ? b : (Float.isNaN(a + b) ? Float.NaN : b)
        // If a > b, it returns b (unless a+b is NaN, then it returns NaN).
        // This implementation logic is actually quite unusual for a 'max' function, 
        // but we test exactly what is written.
        float expected = 5.0f;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_aGreaterThanB_WithNaNResult() {
        // To trigger the Float.isNaN(a + b) branch:
        // If a > b, and a + b is NaN.
        float a = Float.NaN;
        float b = 1.0f;
        // a <= b is false for NaN.
        // a + b is NaN.
        // Result should be NaN.
        float result = FastMath.max(a, b);
        assertTrue(Float.isNaN(result));
    }

    @Test
    public void testMax_BothNaN() {
        float a = Float.NaN;
        float b = Float.NaN;
        // a <= b is false for NaN.
        // a + b is NaN.
        // Result should be NaN.
        float result = FastMath.max(a, b);
        assertTrue(Float.isNaN(result));
    }

    @Test
    public void testMax_NegativeValues() {
        float a = -1.0f;
        float b = -2.0f;
        // a <= b is false (-1 <= -2 is false).
        // a + b = -3.0f (not NaN).
        // returns b -> -2.0f.
        float expected = -2.0f;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }

    @Test
    public void testMax_Infinity() {
        float a = Float.POSITIVE_INFINITY;
        float b = Float.NEGATIVE_INFINITY;
        // a <= b is false.
        // a + b = Infinity.
        // returns b -> -Infinity.
        float expected = Float.NEGATIVE_INFINITY;
        assertEquals(expected, FastMath.max(a, b), 0.0f);
    }
}
